<?php
namespace App\Services\Reporting;
class ExcelStatementExporter {
 public function make(array $r):string {
  $s=[];$s[]=$this->sheet('Summary',[['Supun AeroSoft (Pvt) Ltd'],['Financial Statements'],['Period',$r['period']['from'].' to '.$r['period']['to']],[],['Metric','LKR'],['Revenue',$r['profit_loss']['revenue']],['Expenses',$r['profit_loss']['expenses_total']],['Net profit',$r['profit_loss']['net_profit']],['Total assets',$r['balance_sheet']['assets_total']],['Liabilities and equity',$r['balance_sheet']['liabilities_equity_total']],['Balance check',$r['balance_sheet']['difference']],['Net cash change',$r['cash_flow']['net_change']]]);
  $pl=[['Supun AeroSoft (Pvt) Ltd'],['Profit and Loss'],['Period',$r['period']['from'].' to '.$r['period']['to']],[],['Account','LKR']];foreach($r['profit_loss']['income'] as $x)$pl[]=[$x['code'].' '.$x['account'],$x['amount']];$pl[]=['Total revenue',$r['profit_loss']['revenue']];foreach($r['profit_loss']['expenses'] as $x)$pl[]=[$x['code'].' '.$x['account'],$x['amount']];$pl[]=['Total expenses',$r['profit_loss']['expenses_total']];$pl[]=['Net profit',$r['profit_loss']['net_profit']];$s[]=$this->sheet('Profit and Loss',$pl);
  $bs=[['Supun AeroSoft (Pvt) Ltd'],['Balance Sheet'],['As at',$r['period']['to']],[],['Account','LKR']];foreach($r['balance_sheet']['assets'] as $x)$bs[]=[$x['code'].' '.$x['account'],$x['amount']];$bs[]=['Total assets',$r['balance_sheet']['assets_total']];foreach($r['balance_sheet']['liabilities_equity'] as $x)$bs[]=[$x['code'].' '.$x['account'],$x['amount']];$bs[]=['Current-period profit',$r['balance_sheet']['current_profit']];$bs[]=['Total liabilities and equity',$r['balance_sheet']['liabilities_equity_total']];$bs[]=['Balance difference',$r['balance_sheet']['difference']];$s[]=$this->sheet('Balance Sheet',$bs);
  $cf=[['Supun AeroSoft (Pvt) Ltd'],['Cash Flow Statement'],['Period',$r['period']['from'].' to '.$r['period']['to']],[],['Activity','LKR'],['Operating activities',$r['cash_flow']['operating']],['Investing activities',$r['cash_flow']['investing']],['Financing activities',$r['cash_flow']['financing']],['Net change in cash',$r['cash_flow']['net_change']]];$s[]=$this->sheet('Cash Flow',$cf);
  $tb=[['Supun AeroSoft (Pvt) Ltd'],['Trial Balance'],['Period',$r['period']['from'].' to '.$r['period']['to']],[],['Code','Account','Type','Debit','Credit','Balance']];foreach($r['trial_balance'] as $x)$tb[]=[$x['code'],$x['account'],$x['type'],$x['debit'],$x['credit'],$x['balance']];$s[]=$this->sheet('Trial Balance',$tb);
  return '<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Default"><Font ss:FontName="Arial" ss:Size="10"/></Style><Style ss:ID="Title"><Font ss:Bold="1" ss:Size="14"/></Style><Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#17365D" ss:Pattern="Solid"/></Style><Style ss:ID="Money"><NumberFormat ss:Format="#,##0.00;[Red](#,##0.00);-"/></Style></Styles>'.implode('',$s).'</Workbook>';
 }
 private function sheet(string $name,array $rows):string {$xml='<Worksheet ss:Name="'.$this->e($name).'"><Table><Column ss:Width="220"/><Column ss:Width="120"/><Column ss:Width="100"/><Column ss:Width="100"/><Column ss:Width="100"/><Column ss:Width="100"/>';foreach($rows as $i=>$row){$xml.='<Row>';foreach($row as $v){$style=$i<2?'Title':($i===4?'Header':(is_numeric($v)?'Money':'Default'));$type=is_numeric($v)?'Number':'String';$xml.='<Cell ss:StyleID="'.$style.'"><Data ss:Type="'.$type.'">'.$this->e((string)$v).'</Data></Cell>';}$xml.='</Row>';}$xml.='</Table><WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel"><FreezePanes/><FrozenNoSplit/><SplitHorizontal>5</SplitHorizontal><TopRowBottomPane>5</TopRowBottomPane><ProtectObjects>False</ProtectObjects><ProtectScenarios>False</ProtectScenarios></WorksheetOptions></Worksheet>';return $xml;}
 private function e(string $v):string{return htmlspecialchars($v,ENT_XML1|ENT_QUOTES,'UTF-8');}
}
